update public.fields set verification_status='verified_against_standard', verification_quote='Para los lugares de muestreo que incluyan un dispositivo de muestreo automático fijo, se deberá disponer de las siguientes instalaciones de muestreo: - Acceso para los vehículos de motor a las inmediaciones del lugar de muestreo - Superficies de trabajo planas a una altura adecuada por encima del punto de muestreo para la instalación de los dispositivos de muestreo ; - Iluminación y conexión eléctrica adecuadas - Conexión de agua para limpiar el equipo después del muestreo - Precauciones de seguridad adecuadas (por ejemplo, rejillas, barandillas, dispositivos anticaída); - Medidores de caudal en el caso de un muestreo dependiente del caudal. — printed p.4 / PDF p.11', verification_note='VA-verified 2026-09-08 (§4.2, printed p.4 / PDF p.11) [VA] — "se deberá disponer" is shall-class but scoped to sites with a FIXED automatic sampling device; the field is is_required=false, which matches that conditional scope', verified_at=now() where id='34c0783d-7efa-4123-b0b6-28cdabf81f66' and verification_status not in ('verified_against_standard','corrected');

-- unusual_hydraulic_conditions_recorded - §4.2, printed p.4 / PDF p.11
update public.fields set verification_status='verified_against_standard', verification_quote='Si las condiciones hidráulicas no garantizan la representatividad de la muestra (ausencia de flujo, actividad reducida actividad, aumento anormal de la carga), esta situación inusual debe anotarse en el informe de muestreo y el cliente y al laboratorio de análisis. — printed p.4 / PDF p.11', verification_note='VA-verified 2026-09-08 (§4.2, printed p.4 / PDF p.11) [VA] — the obligation is CONDITIONAL ("Si las condiciones hidráulicas no garantizan..."), yet block gate CR-006 demands the flag be true unconditionally, so a site with normal hydraulics can never satisfy it (STAGED R-6)', verified_at=now() where id='81b2ebee-c445-4ebf-858d-087bfb1006bd' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-03 "Probenahmehaeufigkeit & -zeitpunkt" (8 rows) ----------

-- number_of_samples - §4.3.1 Número de muestras, printed p.4 / PDF p.11
update public.fields set verification_status='verified_against_standard', verification_quote='La decisión sobre el número necesario de muestras tomadas durante cada período debe decidirse basándose en técnicas estadísticas (véase ISO 2602,[1] ISO 3534 (todas las partes)[2] e ISO 5667-1). Pero el número de muestras a tomar puede ser decidido a menudo por el organismo regulador o las autoridades de control de la contaminación. — printed p.4 / PDF p.11', verification_note='VA-verified 2026-09-08 (§4.3.1 Número de muestras, printed p.4 / PDF p.11) [VA] — the clause fixes NO number; it defers to ISO 2602 / ISO 3534 / ISO 5667-1 or the regulator (NR for any numeric limit). The obligation is about the METHOD of deciding n, not about n itself', verified_at=now() where id='ae8b2a13-fc2b-4ef1-b316-d721c2f88e04' and verification_status not in ('verified_against_standard','corrected');

-- A - §4.3.2, "Donde" legends of Fórmula (1) and Fórmula (2), printed p.5 / PDF p.12
update public.fields set verification_status='verified_against_standard', verification_quote='Donde n Número de muestras; A Número aleatorio en un intervalo entre – 365/n y 0. | Donde n Número de muestras; A Número aleatorio en un intervalo entre – 52/n y 0. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, "Donde" legends of Fórmula (1) and Fórmula (2), printed p.5 / PDF p.12) [VA] — READ FROM THE RENDERED PAGE IMAGE (PDF p.12 at 150 dpi) because the extraction of this page carries 144 of the 246 undecodable characters in this file. The image confirms the sign is a MINUS ("entre – 365/n y 0"), i.e. A is non-positive. The stored equation source_quotes print this bound as "± 365/n" / "± 52/n", which the page does NOT say (STAGED R-13)', verified_at=now() where id='f4028c97-8527-4674-934c-5792cd888e4f' and verification_status not in ('verified_against_standard','corrected');

-- k - §4.3.2, printed p.5 / PDF p.12
update public.fields set verification_status='verified_against_standard', verification_quote='La fórmula (1) indica el número de días durante los cuales debe realizarse el muestreo. | La fórmula (2) indica el número de la semana durante la cual debe realizarse el muestreo. El día de cada semana debe determinarse de manera que las muestras se tomen todos los días de la semana. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, printed p.5 / PDF p.12) [VA] — PARTIAL SUPPORT. The letter "k" appears NOWHERE in this document. The printed formulas are written as an explicit SERIES (A + 365/n, A + 365x2/n, A + 365x3/n, ..., A + 365xn/n), read from the rendered page image at PDF p.12. "k" is an EKOWAI index parameterisation of that printed series, not a printed symbol (STAGED R-14)', verified_at=now() where id='6ea44d1b-7bed-4682-bfd5-bf0b8e0cbb8c' and verification_status not in ('verified_against_standard','corrected');

-- sampling_day_k - §4.3.2 Tiempo de muestreo de la corriente de efluentes, printed p.5 / PDF p.12
update public.fields set verification_status='verified_against_standard', verification_quote='si el período de muestreo abarca un año, los días de muestreo pueden determinarse mediante una fórmula. Un ejemplo es: | Fórmula (1) para un número de muestras (n), superior a unas 25 y de la Fórmula (2) para un número de muestras inferior a unas 25. | La fórmula (1) indica el número de días durante los cuales debe realizarse el muestreo. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2 Tiempo de muestreo de la corriente de efluentes, printed p.5 / PDF p.12) [VA] — the printed series A + 365/n, A + 365x2/n, ..., A + 365xn/n was read from the rendered page image (PDF p.12); it matches the encoded formula A + 365*k/n. NOTE the printed framing: "los días de muestreo PUEDEN determinarse mediante una fórmula. Un ejemplo es" - the formula is explicitly an EXAMPLE, not a mandatory method. The "superior a unas 25" applicability condition is encoded in the description and is correct', verified_at=now() where id='15bec5b5-6d92-4c34-9634-47cfbdc8c63f' and verification_status not in ('verified_against_standard','corrected');

-- sampling_week_k - §4.3.2, printed p.5 / PDF p.12
update public.fields set verification_status='verified_against_standard', verification_quote='Fórmula (1) para un número de muestras (n), superior a unas 25 y de la Fórmula (2) para un número de muestras inferior a unas 25. | La fórmula (2) indica el número de la semana durante la cual debe realizarse el muestreo. El día de cada semana debe determinarse de manera que las muestras se tomen todos los días de la semana. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, printed p.5 / PDF p.12) [VA] — PRINTING DEFECT IN THE SOURCE, confirmed on the rendered image (PDF p.12): Fórmula (2) is printed as "B + 52/n, B + 52x2/n, A + 52x3/n, ..., A + 52xn/n" - the first two terms use B, the rest A, and the "Donde" legend defines only n and A. B is never defined anywhere in the document. The encoding uses A throughout, which is the only reading the legend supports (STAGED R-15)', verified_at=now() where id='1a2b5f2f-2059-44e6-ad6d-985b8a6c5f79' and verification_status not in ('verified_against_standard','corrected');

-- variation_source - §4.3.2, printed p.4 / PDF p.11
update public.fields set verification_status='verified_against_standard', verification_quote='En general, al tomar muestras de aguas residuales y efluentes, es normal tener en cuenta las siguientes fuentes de variación de la calidad: a) las variaciones diurnas (es decir, la variabilidad dentro del día) b) variaciones entre días de la semana c) variaciones entre semanas y meses d) variaciones entre estaciones; e) variaciones debidas a episodios de aguas pluviales; y f) tendencias. — printed p.4 / PDF p.11', verification_note='VA-verified 2026-09-08 (§4.3.2, printed p.4 / PDF p.11) [VA] — the six enum values reproduce a)-f) exactly. CAVEAT: the printed list is CONJUNCTIVE ("tener en cuenta las siguientes fuentes", all of them) while the field is a single-select enum (STAGED R-16). The sentence carries no modal verb, yet gate CR-009 forces the field non-null', verified_at=now() where id='acad4ff6-d945-4473-917b-66f3756d281e' and verification_status not in ('verified_against_standard','corrected');

-- peak_load_targeted - §4.3.2, printed p.4 / PDF p.11
update public.fields set verification_status='verified_against_standard', verification_quote='Si la identificación de la naturaleza y la magnitud de la carga máxima son importantes, el muestreo debe limitarse a los períodos del día, la semana o el mes en que se sabe que se producen las cargas máximas. — printed p.4 / PDF p.11', verification_note='VA-verified 2026-09-08 (§4.3.2, printed p.4 / PDF p.11) [VA] — conditional obligation ("Si la identificación ... son importantes"); the field is correctly is_required=false and carries no gate', verified_at=now() where id='53abf550-308b-4fd6-a6d7-b3617161a497' and verification_status not in ('verified_against_standard','corrected');

-- sampling_period - §4.3.2, printed p.5 / PDF p.12
update public.fields set verification_status='verified_against_standard', verification_quote='Normalmente, las muestras deben tomarse a intervalos fijos durante todo el período de control. El período de muestreo puede ser de un año, de varios meses o semanas, o incluso de períodos más cortos. | El periodo elegido debe abarcar cualquier variación estacional. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, printed p.5 / PDF p.12) [VA] — the four enum values (year / several months / weeks / shorter) reproduce the printed disjunction exactly; single-select is correct here', verified_at=now() where id='d698fb24-6e53-4517-9ccf-fd9b765657b3' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-04 "Probenahme an spezifischen Standorten" (8 rows) ----------

-- specific_site_type - Clause 5 subclause headings 5.1-5.4, printed p.6-8 / PDF p.13-15
update public.fields set verification_status='verified_against_standard', verification_quote='5.1. Muestreo de alcantarillas, canales y pozos de registro — printed p.6 / PDF p.13', verification_note='VA-verified 2026-09-08 (Clause 5 subclause headings 5.1-5.4, printed p.6-8 / PDF p.13-15) [VA] — verified against the four printed subclause headings of Clause 5: 5.1 "Muestreo de alcantarillas, canales y pozos de registro" (printed p.6), 5.2 "Muestreo de las plantas de tratamiento de aguas residuales" (printed p.7), 5.3 "Muestreo de los emplazamientos industriales" (printed p.7), 5.4 "Muestreo de los sistemas de refrigeración" (printed p.8). The quote carries the 5.1 heading; the other three are cited in this note because a single verbatim run cannot span four pages. Clause 5 contains no obligation to declare a site type - CR-010 is a presence check over a field that is already is_required (STAGED R-9)', verified_at=now() where id='25903275-6b6b-4411-860c-85e42730ae6a' and verification_status not in ('verified_against_standard','corrected');

-- sampling_depth_fraction - §5.1, printed p.6 / PDF p.13
update public.fields set verification_status='verified_against_standard', verification_quote='El punto de muestreo debe estar a una distancia mínima del fondo y de las paredes para evitar la contaminación de la muestra por los depósitos o las biopelículas que se desarrollan. En general, puede recomendarse un punto de muestreo entre un tercio y la mitad de la profundidad del agua del efluente por debajo de la superficie del agua. — printed p.6 / PDF p.13', verification_note='VA-verified 2026-09-08 (§5.1, printed p.6 / PDF p.13) [VA] — PRINTED RANGE, NOT ENFORCED. The modal is "puede recomendarse" (may be recommended) and the value is a range 1/3..1/2. No gate reads this field, so the printed range is neither surfaced as an SR-2 selection nor bounded (STAGED R-17)', verified_at=now() where id='20df9ea4-d27f-4720-b69c-bd8e97a47296' and verification_status not in ('verified_against_standard','corrected');

-- restriction_downstream_diameters - §5.1, printed p.6 / PDF p.13
update public.fields set verification_status='verified_against_standard', verification_quote='En ausencia de un lugar con condiciones de flujo turbulento en el lugar de muestreo permanente, dichas condiciones deben inducirse restringiendo el flujo, por ejemplo, con un deflector o una presa. | El punto de toma de muestras debe estar siempre situado aguas abajo de la restricción y, como norma general, debe situarse al menos tres veces el diámetro de la tubería, o la anchura del canal, aguas abajo de la restricción. — printed p.6 / PDF p.13', verification_note='VA-verified 2026-09-08 (§5.1, printed p.6 / PDF p.13) [VA] — "al menos tres veces el diámetro" confirms the >= 3 in block gate CR-011. CAVEAT: the requirement presupposes that a flow RESTRICTION exists (first run quoted above) and sits in §5.1, which covers sewers/channels/manholes only; CR-011 carries no scope predicate for either (STAGED R-10)', verified_at=now() where id='7037b6cf-d14b-46e9-b7fa-dbcd2bc5e8dc' and verification_status not in ('verified_against_standard','corrected');

-- wwtp_sampling_objective - §5.2 Muestreo de las plantas de tratamiento de aguas residuales, printed p.7 / PDF p.14
update public.fields set verification_status='verified_against_standard', verification_quote='Los objetivos típicos son - control del rendimiento de toda la planta de tratamiento: las muestras deben recogerse en los principales puntos de entrada y de salida; - control del funcionamiento de las unidades de tratamiento individuales, o de grupos de unidades: las muestras deben recogerse en la entrada y la salida de las unidades en cuestión. — printed p.7 / PDF p.14', verification_note='VA-verified 2026-09-08 (§5.2 Muestreo de las plantas de tratamiento de aguas residuales, printed p.7 / PDF p.14) [VA] — CAVEAT: the printed list is OPEN ("Los objetivos TÍPICOS son"); the 2-value enum closes it (STAGED R-18)', verified_at=now() where id='876dd118-68e3-4fad-9a02-fc8fba6e6c54' and verification_status not in ('verified_against_standard','corrected');

-- bypass_flow_assessed - §5.2, printed p.7 / PDF p.14
update public.fields set verification_status='verified_against_standard', verification_quote='Al tomar muestras en las plantas de tratamiento de aguas residuales, debe evaluarse la relevancia de cualquier flujo de derivación y del muestreo de estos flujos ya que puede ser necesario para que el muestreo sea representativo del efluente global. — printed p.7 / PDF p.14', verification_note='VA-verified 2026-09-08 (§5.2, printed p.7 / PDF p.14) [VA] — "debe evaluarse" is shall-class but scoped to WWTP sampling; the field is is_required=false and carries no gate, which is consistent with the conditional scope', verified_at=now() where id='6eea4ca2-6b19-45db-adfd-46cebd980032' and verification_status not in ('verified_against_standard','corrected');

-- cooling_system_type - §5.4 Muestreo de los sistemas de refrigeración, printed p.8 / PDF p.15
update public.fields set verification_status='verified_against_standard', verification_quote='En los sistemas de refrigeración de flujo continuo, se utiliza agua dulce (agua subterránea, filtrado de banco, agua superficial) o agua salina y se utilizan en un flujo o en varios. Los puntos de muestreo se sitúan tanto delante como detrás de los agregados, que serán enfriados. Durante el enfriamiento a través del circuito primario y/o secundario, se acoplan dos circuitos de enfriamiento en los que un circuito secundario cerrado se refrigera con un circuito primario. | En el proceso de enfriamiento cerrado, el agua de refrigeración fluye a través de tuberías, que son enfriadas desde el exterior por aire o agua. — printed p.8 / PDF p.15', verification_note='VA-verified 2026-09-08 (§5.4 Muestreo de los sistemas de refrigeración, printed p.8 / PDF p.15) [VA] — the three enum values reproduce the three printed cooling arrangements. The printed sampling-point rule for the coupled and the closed arrangement is the same sentence, "El lugar de muestreo debe estar en el lado de retorno", which is not itself encoded as a field', verified_at=now() where id='29c432a1-2779-4af3-bb0d-e9df9308d82c' and verification_status not in ('verified_against_standard','corrected');

-- cooling_runoff_time - §5.4, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='En una instalación de muestreo (grifo de muestreo que permita la desinfección, preferiblemente por flameo, y el vaciado) se dejará correr el agua durante al menos 30 s antes del muestreo. — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (§5.4, printed p.9 / PDF p.16) [VA] — "al menos 30 s" confirms the >= 30 in block gate CR-012; unit s is correct. CAVEAT: the sentence is scoped to a cooling-water sampling installation (§5.4) and CR-012 carries no scope predicate (STAGED R-10)', verified_at=now() where id='2e2d8ad8-40e0-4f3d-8458-9caa631f29ed' and verification_status not in ('verified_against_standard','corrected');

-- upstream_of_biocide - §5.4, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='El muestreo se realizará de manera que los resultados no se vean distorsionados por la dosificación de biocidas. El lugar de muestreo estará situado aguas arriba del punto de dosificación del biocida. Si el muestreo no es posible en este lugar, la muestra puede tomarse del agua pulverizada o mediante fianza de la cuenca de agua circulante[3]. — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (§5.4, printed p.9 / PDF p.16) [VA] — "estará situado" is shall-class, yet NO gate reads this field: the printed obligation is unenforced, while the weaker 30 s run-off in the same paragraph is a block gate (STAGED R-19). The printed sentence also carries an escape clause ("Si el muestreo no es posible en este lugar")', verified_at=now() where id='83bac5d9-24ca-4e60-97b4-4daa544c19e3' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-05 "Haupttypen der Abwasserprobenahme" (3 rows) ----------

-- main_sampling_type - Clause 6 and its two subclauses 6.1 / 6.2, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='6 Principales tipos de muestreo de aguas residuales | 6.1 Muestreo puntual | 6.2 Muestreo compuesto | El muestreo compuesto consiste en varias muestras discretas. Puede realizarse de forma automática o manual (véase el anexo B). — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (Clause 6 and its two subclauses 6.1 / 6.2, printed p.9 / PDF p.16) [VA] — Clause 6 has exactly the two subclauses the enum offers. It states NO obligation to declare a type; warn gate CR-013 is a presence check over a field that is already is_required (STAGED R-9)', verified_at=now() where id='b5259a50-53a1-44f9-b6d2-c50c4b1ef02d' and verification_status not in ('verified_against_standard','corrected');

-- grab_method - §6.1 Muestreo puntual, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='En el caso del muestreo puntual (véase el anexo B), es posible realizar: a) muestreo directo en la masa de agua residual: 1. Directamente, utilizando botellas de laboratorio 2. Utilizando un recolector de muestras lastrado y equipado con botellas de laboratorio 3. Utilizando un muestreador automático. b) muestreo indirecto en la masa de agua residual 1. Utilizando una barra de muestreo equipada con un recipiente de recogida; 2. Utilizando un cubo u otro equipo. — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (§6.1 Muestreo puntual, printed p.9 / PDF p.16) [VA] — the five enum values reproduce a)1-3 and b)1-2 exactly. The clause references "el anexo B", which is NOT PRESENT in the library copy of this document (NR)', verified_at=now() where id='f6363e13-2cad-41e3-9972-e19681a2e0c8' and verification_status not in ('verified_against_standard','corrected');

-- composite_mode - §6.2 Muestreo compuesto, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='Para el muestreo compuesto automático, existen varios tipos de muestra compuesta (véase la norma ISO 5667-1). Es posible implementar: - muestreo de volumen constante y tiempo variable (C.V.V.T) - muestreo de volumen variable de tiempo constante (C.T.V.V) - muestreo de volumen constante en tiempo constante (C.T.C.V) Para el muestreo compuesto manual, este enfoque es equivalente al muestreo con tiempo fijo, flujo fijo y volumen fijo. — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (§6.2 Muestreo compuesto, printed p.9 / PDF p.16) [VA] — the four enum values (CVVT / CTVV / CTCV / manual) reproduce the printed list. §7.2.2.2 (printed p.13) confirms CVVT and CTVV are the flow-proportional pair and §7.2.2.4 (printed p.14) confirms CTCV is time-proportional, as the encoded description says', verified_at=now() where id='519743ba-255b-4256-821b-2ac0fcd364dd' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-06 "Durchfuehrung der Probenahme" (18 rows) ----------

-- sampling_objective_defined - §7.1 Aspectos generales, printed p.9 / PDF p.16
update public.fields set verification_status='verified_against_standard', verification_quote='El cliente debe definir claramente el objetivo del muestreo para que el operario aplique las estrategias de muestreo adecuadas. — printed p.9 / PDF p.16', verification_note='VA-verified 2026-09-08 (§7.1 Aspectos generales, printed p.9 / PDF p.16) [VA] — "debe definir" is shall-class. Block gate CR-014 sits on worksheet 05 while this field lives on worksheet 06 (mis-homed; STAGED R-5)', verified_at=now() where id='5038da73-9031-4871-851d-4b4c116f3c6f' and verification_status not in ('verified_against_standard','corrected');

-- sampling_line_length_diameters - §7.1.2 Llegada a la sede, printed p.10 / PDF p.17
update public.fields set verification_status='verified_against_standard', verification_quote='Al colocar las líneas de muestreo, deben evitarse los tramos de tubería horizontales más largos. La longitud de las líneas de muestreo debe ser al menos cinco veces el diámetro de la tubería desde el colector para garantizar un muestreo en la zona totalmente mezclada. — printed p.10 / PDF p.17', verification_note='VA-verified 2026-09-08 (§7.1.2 Llegada a la sede, printed p.10 / PDF p.17) [VA] — "al menos cinco veces el diámetro" confirms the >= 5 in block gate CR-015; the field is a dimensionless multiple, so unit "-" is correct', verified_at=now() where id='34d21c52-af42-4aa1-be7c-8fb4adceb19f' and verification_status not in ('verified_against_standard','corrected');

-- composite_interval - §7.2.1 Generalidades, printed p.11 / PDF p.18
update public.fields set verification_status='verified_against_standard', verification_quote='Para el muestreo discontinuo, seleccione los intervalos más cortos posibles entre las muestras individuales. No deben superar los 5 minutos para la muestra mixta de 2 horas y los 30 minutos para la muestra mixta de 24 horas. — printed p.11 / PDF p.18', verification_note='VA-verified 2026-09-08 (§7.2.1 Generalidades, printed p.11 / PDF p.18) [VA] — TWO printed limits, keyed to the composite duration: 5 min for a 2 h composite and 30 min for a 24 h composite. The field description states both correctly, but block gate CR-016 enforces only "composite_interval <= 30", i.e. the LOOSER of the two, and there is no field carrying the composite duration to discriminate on. A 2 h composite at 20 min intervals passes the gate and violates the page (STAGED R-3)', verified_at=now() where id='d4dc4477-d5f5-42f3-8239-502d5c402fc4' and verification_status not in ('verified_against_standard','corrected');

-- tube_internal_diameter - §7.2.2.1 Recomendaciones generales sobre el uso de un muestreador automático, printed p.12 / PDF p.19
update public.fields set verification_status='verified_against_standard', verification_quote='- Sistema de muestreo y tubo de salida al contenedor: - deben ser lo más cortos posible, inertes con respecto a las sustancias deseadas y siempre en posición ascendente para evitar la formación de depósitos (evitar curvas, sifones, rodamientos) - debe tener un diámetro interno mayor o igual a 9 mm; — printed p.12 / PDF p.19', verification_note='VA-verified 2026-09-08 (§7.2.2.1 Recomendaciones generales sobre el uso de un muestreador automático, printed p.12 / PDF p.19) [VA] — "mayor o igual a 9 mm" confirms the >= 9 (inclusive) in block gate CR-017; unit mm correct. The whole of §7.2.2.1 is introduced as "se recomienda seguir los siguientes puntos" (recommended), which the block severity does not reflect (STAGED R-4)', verified_at=now() where id='29aac76a-aa0d-417b-bb56-e1950bdb61b1' and verification_status not in ('verified_against_standard','corrected');

-- suction_velocity - §7.2.2.1 including NOTE 1, printed p.12 / PDF p.19
update public.fields set verification_status='verified_against_standard', verification_quote='Velocidad de aspiración: no debe ser inferior a 0,5 m/s para evitar la segregación de la materia en suspensión en el | NOTA 1 Pueden ser posibles velocidades de aspiración inferiores si se demuestra que son satisfactorias. Un ejemplo es cuando el diámetro interno del tubo de aspiración es de 12 mm o más, en cuyo caso se ha demostrado que una velocidad de aspiración de 0,3 m/s es aceptable[5]. — printed p.12 / PDF p.19', verification_note='VA-verified 2026-09-08 (§7.2.2.1 including NOTE 1, printed p.12 / PDF p.19) [VA] — "no debe ser inferior a 0,5 m/s" confirms >= 0.5 in block gate CR-017. The printed page immediately grants an EXCEPTION in NOTE 1 (0,3 m/s where the internal diameter is 12 mm or more); the field description carries the exception but the block gate does not, so a compliant 0,3 m/s installation is blocked (STAGED R-4). The printed sentence is broken mid-clause by a typesetting repetition on the page ("...en suspensión en el / para evitar la segregación de la materia en suspensión en el bucle de muestreo"), so it is quoted up to the break', verified_at=now() where id='4a744869-d3fc-49e2-84be-c51deb5e712e' and verification_status not in ('verified_against_standard','corrected');

-- unit_volume - §7.2.2.1, printed p.12 / PDF p.19
update public.fields set verification_status='verified_against_standard', verification_quote='- Volumen de la unidad: - debe ser adecuado para garantizar un muestreo representativo (por ejemplo, al menos 50 ml para la bomba de vacío o 25 ml para el émbolo en línea); — printed p.12 / PDF p.19', verification_note='VA-verified 2026-09-08 (§7.2.2.1, printed p.12 / PDF p.19) [VA] — the two numbers are inside an EXAMPLE parenthetical ("por ejemplo"); the printed obligation is only that the unit volume "debe ser adecuado". The field description drops the "por ejemplo" and block gate CR-018 enforces the LOWER example value (>= 25) for every pump technology, so a vacuum-pump sampler at 30 ml passes although the page names 50 ml for that pump; the pump_technology field that could discriminate is read by no gate (STAGED R-1)', verified_at=now() where id='42e6e9fa-2168-4bf0-bf11-f86b8c60a981' and verification_status not in ('verified_against_standard','corrected');

-- sampling_bias - §7.2.2.1, printed p.12 / PDF p.19
update public.fields set verification_status='verified_against_standard', verification_quote='el sesgo no deberá ser superior al 10 %; — printed p.12 / PDF p.19', verification_note='VA-verified 2026-09-08 (§7.2.2.1, printed p.12 / PDF p.19) [VA] — "no deberá ser superior al 10 %" confirms <= 10 (inclusive) in block gate CR-018; unit % correct', verified_at=now() where id='118db3e9-9f00-4334-a9bd-99cad2078986' and verification_status not in ('verified_against_standard','corrected');

-- repeatability_cv - §7.2.2.1, printed p.12-13 / PDF p.19-20
update public.fields set verification_status='verified_against_standard', verification_quote='la repetibilidad no será superior al 5 %. | La mayoría de los muestreadores automáticos tienen un coeficiente de variación de la repetibilidad del 5 % como máximo para un volumen de 250 ml. Por lo tanto, si se trabaja con un volumen inferior, deberá validarse antes de su aplicación y comprobar si cumple los requisitos. — printed p.12 and p.13 / PDF p.19 and p.20', verification_note='VA-verified 2026-09-08 (§7.2.2.1, printed p.12-13 / PDF p.19-20) [VA] — "no será superior al 5 %" confirms <= 5 (inclusive) in block gate CR-018; the 250 ml / smaller-volume-validation sentence in the description is on the next printed page and is quoted as the second run', verified_at=now() where id='05123520-8930-472a-9c94-d7537098fe06' and verification_status not in ('verified_against_standard','corrected');

-- flow_uncertainty_k2 - §7.2.2.1, printed p.13 / PDF p.20
update public.fields set verification_status='verified_against_standard', verification_quote='La incertidumbre de gasto resultante U (k=2) no será superior al 15 % (véase el anexo I). — printed p.13 / PDF p.20', verification_note='VA-verified 2026-09-08 (§7.2.2.1, printed p.13 / PDF p.20) [VA] — "no será superior al 15 %" confirms <= 15 (inclusive) in block gate CR-018. The referenced "anexo I" is NOT PRESENT in the library copy of this document, so the method behind the uncertainty budget is NR', verified_at=now() where id='0eeb9516-26b9-455e-bca1-042ef5c35bdd' and verification_status not in ('verified_against_standard','corrected');

-- sampler_flow_linked - §7.2.2.2 Muestreo compuesto automático, muestreo proporcional al caudal (C.V.V.T y C.T.V.V), printed p.13 / PDF p.20
update public.fields set verification_status='verified_against_standard', verification_quote='Estos métodos de muestreo son los más representativos de la masa a tomar y son esenciales para caracterizar un flujo de contaminantes. Para ello es necesario que el muestreador automático esté conectado a un caudalímetro. Existen dos tipos principales de dispositivos de medición de flujo para controlar el muestreo en el caudal: - dispositivos en línea cerrada con sensores electromagnéticos o ultrasónicos; - dispositivos en canal abierto equipados con diversos sensores (ultrasónicos, piezoresistivos, de burbuja, altura/velocidad). — printed p.13 / PDF p.20', verification_note='VA-verified 2026-09-08 (§7.2.2.2 Muestreo compuesto automático, muestreo proporcional al caudal (C.V.V.T y C.T.V.V), printed p.13 / PDF p.20) [VA] — "es necesario" is shall-class but scoped to flow-proportional composite sampling; the field is is_required=false and carries no gate, which matches the conditional scope', verified_at=now() where id='84d78b64-ae97-427c-ad5b-42bca0db153a' and verification_status not in ('verified_against_standard','corrected');

-- V_final - §7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21
update public.fields set verification_status='verified_against_standard', verification_quote='Vfinal: volumen total (ml) de las botellas del laboratorio — printed p.14 / PDF p.21', verification_note='VA-verified 2026-09-08 (§7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21) [VA] — read from the rendered page image at PDF p.21 as well as the text layer; unit ml correct', verified_at=now() where id='e8c74d0c-9ccb-4948-a579-8dcf9f3ead4f' and verification_status not in ('verified_against_standard','corrected');

-- M3_total - §7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21
update public.fields set verification_status='verified_against_standard', verification_quote='M3total: volumen total descargado (M3) — printed p.14 / PDF p.21', verification_note='VA-verified 2026-09-08 (§7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21) [VA] — the page prints the symbol with a superscript 3 and a subscript "total"; the extraction flattens it to "M3total". Confirmed on the rendered page image at PDF p.21. Unit m3 correct', verified_at=now() where id='241090d7-74e7-4fff-acda-dec134365445' and verification_status not in ('verified_against_standard','corrected');

-- M3_n - §7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21
update public.fields set verification_status='verified_against_standard', verification_quote='M3n: volumen descargado durante el muestreo de la botella n (M3) — printed p.14 / PDF p.21', verification_note='VA-verified 2026-09-08 (§7.2.2.3, legend of Fórmula (3), printed p.14 / PDF p.21) [VA] — confirmed on the rendered page image at PDF p.21; unit m3 correct', verified_at=now() where id='5c223b68-25fa-4578-822f-bd13a25ac4e4' and verification_status not in ('verified_against_standard','corrected');

-- V_n - §7.2.2.3, Fórmula (3) and its legend, printed p.13-14 / PDF p.20-21
update public.fields set verification_status='verified_against_standard', verification_quote='Para las demás botellas individuales, toma el volumen (ml) que debe tomarse (Vn) en la botella. n es un porcentaje relativo al volumen total (Fórmula 3): | Vn: volumen de la muestra (ml) a tomar en la botella n — printed p.13 and p.14 / PDF p.20 and p.21', verification_note='VA-verified 2026-09-08 (§7.2.2.3, Fórmula (3) and its legend, printed p.13-14 / PDF p.20-21) [VA] — the formula body itself is one of the two passages destroyed in the text layer, so it was READ FROM THE RENDERED PAGE IMAGE (PDF p.21 at 150 dpi): Vn = [Vfinal x (M3n / M3total)], which matches the encoded equation exactly. Nothing was quoted from the corrupt run', verified_at=now() where id='7d8cd949-0345-42cc-ad6b-9fce86837ad5' and verification_status not in ('verified_against_standard','corrected');

-- grab_depth_below_surface - §7.3.1 Generalidades, printed p.15 / PDF p.22
update public.fields set verification_status='verified_against_standard', verification_quote='A menos que el cliente especifique lo contrario o por una razón técnica, el muestreo se realiza normalmente a unos 30 cm por debajo de la superficie o a media altura de la columna de agua en una zona homogénea para evitar tomar la película superficial o los sedimentos. — printed p.15 / PDF p.22', verification_note='VA-verified 2026-09-08 (§7.3.1 Generalidades, printed p.15 / PDF p.22) [VA] — the printed value is APPROXIMATE and ALTERNATIVE ("a unos 30 cm ... O a media altura de la columna de agua"), and the whole sentence is prefixed by an opt-out ("A menos que el cliente especifique lo contrario"). Warn gate CR-020 turns it into a one-sided minimum grab_depth_below_surface >= 30 (STAGED R-20)', verified_at=now() where id='78fa700f-61da-4e1f-838a-e3bc473376cb' and verification_status not in ('verified_against_standard','corrected');

-- event_triggered_sampling - §7.3.4 Muestreo automático, de inicio remoto o activado por eventos, printed p.17 / PDF p.24; definition §3.10, printed p.3 / PDF p.10
update public.fields set verification_status='verified_against_standard', verification_quote='El muestreo automático activado por eventos, basado en la monitorización en línea en tiempo real | de los parámetros de las aguas residuales, aumenta la posibilidad de obtener una muestra representativa de la calidad real de las aguas residuales en ese momento específico. | El muestreo que se desencadena porque se ha cumplido un criterio predeterminado (por ejemplo, precipitaciones, cambios en conductividad eléctrica, el pH o la introducción de una sustancia contaminante), cuando las muestras deben tomarse manualmente o con equipos automáticos. — printed p.17 and p.3 / PDF p.24 and p.10', verification_note='VA-verified 2026-09-08 (§7.3.4 Muestreo automático, de inicio remoto o activado por eventos, printed p.17 / PDF p.24; definition §3.10, printed p.3 / PDF p.10) [VA] — the §7.3.4 sentence is split across two lines by a stray blank line in the extraction and is quoted as two runs; the third run is the §3.10 definition the field description cites. The clause states a benefit, not an obligation, and the field carries no gate', verified_at=now() where id='9451f4b3-57bc-44d0-9ef3-0c99baa4f01e' and verification_status not in ('verified_against_standard','corrected');

-- tank_mixing_maintained - §7.4 Muestreo puntual de las cisternas - vertidos previstos, printed p.17 / PDF p.24
update public.fields set verification_status='verified_against_standard', verification_quote='Antes de recoger la muestra, el contenido del tanque debe mezclarse durante un período que debe definir el operativo de muestreo (véase 8.4). | - mantener la mezcla durante el muestreo, y; - tomar medidas para evitar que cualquier efluente fluya en el tanque entre el inicio y el final del muestreo, hasta el final de la descarga autorizada. — printed p.17 / PDF p.24', verification_note='VA-verified 2026-09-08 (§7.4 Muestreo puntual de las cisternas - vertidos previstos, printed p.17 / PDF p.24) [VA] — "debe mezclarse" is shall-class but scoped to cistern sampling for planned discharges; the field is is_required=false and carries no gate, which matches', verified_at=now() where id='505ae7d7-6c3d-403f-aa6a-cae1f3b2c4e9' and verification_status not in ('verified_against_standard','corrected');

-- homogeneity_deviation - §7.4, printed p.18 / PDF p.25
update public.fields set verification_status='verified_against_standard', verification_quote='La desviación máxima tolerada entre dos mediciones del parámetro seleccionado para satisfacer el criterio de homogeneidad será preferentemente inferior al 20 %. | En este caso, se observará la coherencia (desviación inferior al 20 %) entre las mediciones de los parámetros elegidos para la validación. — printed p.18 / PDF p.25', verification_note='VA-verified 2026-09-08 (§7.4, printed p.18 / PDF p.25) [VA] — "preferentemente inferior al 20 %" - the modal is a PREFERENCE and the comparison is STRICT (<20, not <=20). Warn gate CR-021 uses "homogeneity_deviation < 20" and severity warn: both match the page. The second run is the downstream-sampling validation criterion the field description also cites. A THIRD printed 20 % criterion exists at §9.1 (printed p.22) with no field and no gate (STAGED R-21)', verified_at=now() where id='7f149092-558e-4fda-9f80-809398a0ca1d' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-07 "Probenahmeausruestung" (10 rows) ----------

-- material_compatible - §8.1 Generalidades, printed p.18 / PDF p.25
update public.fields set verification_status='verified_against_standard', verification_quote='La naturaleza de los materiales del equipo de muestreo se elegirá en función de su compatibilidad con el parámetro objetivo y deberá garantizar la ausencia de interferencias físico-químicas con los parámetros a medir (véase el anexo E). — printed p.18 / PDF p.25', verification_note='VA-verified 2026-09-08 (§8.1 Generalidades, printed p.18 / PDF p.25) [VA] — "se elegirá ... deberá garantizar" is shall-class. The referenced "anexo E" is NOT PRESENT in the library copy (NR). Block gate CR-022 sits on worksheet 05 while this field lives on worksheet 07 (mis-homed; STAGED R-5)', verified_at=now() where id='653355f2-476f-4ed7-a52d-2a55f0c3915a' and verification_status not in ('verified_against_standard','corrected');

-- prohibited_material_avoided - §8.1, printed p.18 / PDF p.25
update public.fields set verification_status='verified_against_standard', verification_quote='No se deben utilizar los siguientes materiales para las muestras de los parámetros a bajo nivel de concentración[7]: - material que contenga conexiones de latón; - material plástico pigmentado (plástico coloreado); - material de plástico policlorado no alimentario (PVC). Se sabe que estos materiales liberan metales (zinc, cadmio, etc.) y compuestos orgánicos. Si se utilizan estos tipos de materiales (PVC, metal) u otros, será necesario demostrar la ausencia de contaminación o la adsorción del parámetro o parámetros (véase 10.3). — printed p.18 / PDF p.25', verification_note='VA-verified 2026-09-08 (§8.1, printed p.18 / PDF p.25) [VA] — "No se deben utilizar" is shall-class, scoped to low-concentration parameters; the field is correctly is_required=false and carries no gate. Reference [7] points at the Bibliography, which is NOT PRESENT in the library copy (NR)', verified_at=now() where id='92f022e8-57cd-4ffa-8185-a82a1aaf33a9' and verification_status not in ('verified_against_standard','corrected');

-- sampler_mobility - §8.2 Muestreador automático, printed p.19 / PDF p.26
update public.fields set verification_status='verified_against_standard', verification_quote='Los muestreadores automáticos pueden ser fijos o portátiles y también pueden estar equipados con una cámara refrigerada. — printed p.19 / PDF p.26', verification_note='VA-verified 2026-09-08 (§8.2 Muestreador automático, printed p.19 / PDF p.26) [VA] — the two enum values reproduce the printed pair; "pueden ser" is may-class and the field is correctly is_required=false', verified_at=now() where id='ef80665a-00d3-4aec-8296-000a5a6d36ac' and verification_status not in ('verified_against_standard','corrected');

-- sampler_refrigerated - §8.2, printed p.19 / PDF p.26
update public.fields set verification_status='verified_against_standard', verification_quote='El muestreador automático tendrá un compartimento cerrado para llenar y almacenar las muestras recogidas en la oscuridad, y un sistema que permita mantener las muestras a una temperatura compatible con los requisitos de conservación de la norma ISO 5667-3 durante todo el tiempo que dure el muestreo, que puede durar varios días. En algunos casos, y si se requiere de acuerdo con el cliente, es posible el uso de un muestreador automático portátil no refrigerado (por ejemplo, la accesibilidad del punto de muestreo, la estabilidad del analito en condiciones ambientales). — printed p.19 / PDF p.26', verification_note='VA-verified 2026-09-08 (§8.2, printed p.19 / PDF p.26) [VA] — "tendrá" is shall-class, but the very next printed sentence grants an EXCEPTION (a portable non-refrigerated sampler by agreement with the client). Block gate CR-023 forces sampler_refrigerated == true with no exception path and no predicate limiting it to projects that actually use an automatic sampler (STAGED R-7)', verified_at=now() where id='f04c6d1d-d428-4a2a-8941-3dc1153c0474' and verification_status not in ('verified_against_standard','corrected');

-- pump_technology - §8.2, printed p.19 / PDF p.26
update public.fields set verification_status='verified_against_standard', verification_quote='El muestreo de los sistemas de bombeo puede realizarse mediante diferentes tecnologías [por ejemplo, mediante una bomba de vacío (VAP), mediante una bomba peristáltica (PP), mediante un émbolo en línea o utilizando sistemas de bombeo externos]. Las ventajas e inconvenientes de los dos tipos principales de muestreadores se presentan en el Anexo F. — printed p.19 / PDF p.26', verification_note='VA-verified 2026-09-08 (§8.2, printed p.19 / PDF p.26) [VA] — CAVEAT: the printed list is EXEMPLARY ("por ejemplo"); the 4-value enum closes it (STAGED R-18). The referenced "Anexo F" is NOT PRESENT in the library copy (NR). This field is read by no gate, although it is the only thing that could discriminate the 50 ml / 25 ml unit-volume limits of §7.2.2.1 (STAGED R-1)', verified_at=now() where id='691d00b0-96d4-4bc6-97bf-9b1d0156ecc8' and verification_status not in ('verified_against_standard','corrected');

-- manual_min_volume - §8.3.1 Generalidades, printed p.19 / PDF p.26
update public.fields set verification_status='verified_against_standard', verification_quote='El equipo más sencillo para la toma de muestras de efluentes consiste en frascos de laboratorio, colector de muestras lastrado y equipado con frascos de laboratorio, varilla de muestreo equipada con un recipiente o cubo de recogida. El volumen debe ser el adecuado para garantizar un muestreo representativo (25 ml como mínimo). — printed p.19 / PDF p.26', verification_note='VA-verified 2026-09-08 (§8.3.1 Generalidades, printed p.19 / PDF p.26) [VA] — "25 ml como mínimo" is a printed MINIMUM, not an example, and confirms >= 25 in block gate CR-024; unit ml correct', verified_at=now() where id='d6345925-39dd-4310-8041-742f538b8655' and verification_status not in ('verified_against_standard','corrected');

-- manual_repeatability_cv - §8.3.1, printed p.20 / PDF p.27
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando se utilicen muestras manuales para la preparación de muestras compuestas, el volumen del frasco de laboratorio, del recipiente de recogida o del cubo deberá estar bien definido y ser conocido. El coeficiente de variación de la repetibilidad debe estar dentro del ± 5 %. — printed p.20 / PDF p.27', verification_note='VA-verified 2026-09-08 (§8.3.1, printed p.20 / PDF p.27) [VA] — the printed criterion is TWO-SIDED ("dentro del ± 5 %"); block gate CR-024 encodes only "manual_repeatability_cv <= 5", so a value of -6 % passes (STAGED R-22). §7.2.3 (printed p.14) states the same criterion one-sidedly ("inferior o igual al 5 %") for manual composite sampling', verified_at=now() where id='2c1c23cd-12f7-40be-b73a-ab4822a7a4d7' and verification_status not in ('verified_against_standard','corrected');

-- equipment_cleaned_checked - §8.3.1, printed p.20 / PDF p.27
update public.fields set verification_status='verified_against_standard', verification_quote='Antes de iniciar el muestreo, el equipo debe limpiarse (véase el anexo C) y comprobarse (véase 10.3). | El equipo de muestreo debe enjuagarse adecuadamente antes del muestreo y puede lavarse con agua desmineralizada/desionizada o con agua del grifo antes de utilizarlo en la corriente de aguas residuales de la que se toma la muestra para minimizar el riesgo de contaminación. No enjuague el equipo de muestreo en las aguas residuales cuando esto vaya a influir en los análisis que se realicen posteriormente (por ejemplo, análisis de aceites y grasas, efluentes brutos y finales y análisis microbiológicos). — printed p.20 / PDF p.27', verification_note='VA-verified 2026-09-08 (§8.3.1, printed p.20 / PDF p.27) [VA] — "debe limpiarse ... y comprobarse" is shall-class. The referenced "anexo C" (cleaning protocol) is NOT PRESENT in the library copy (NR), so the cleaning standard this field attests to is unreadable from this document', verified_at=now() where id='6cdd4300-b108-4d6e-9b86-62cce381cf85' and verification_status not in ('verified_against_standard','corrected');

-- tank_mixing_system - §8.4.1 Mezcla, printed p.20-21 / PDF p.27-28
update public.fields set verification_status='verified_against_standard', verification_quote='Hay que asegurarse de que la mezcla sea eficaz y no dé lugar a una estratificación del efluente agitado | La mezcla deberá durar un tiempo predefinido, para garantizar la homogeneidad del efluente en el contenedor. El sistema de mezcla en un contenedor puede estar compuesto por uno o varios de los siguientes sistemas: | - uno o varios agitadores mecánicos - burbujeo mediante sobrepresión (aire comprimido, por ejemplo) - recirculación forzada del efluente (boquilla motriz o bomba, por ejemplo). — printed p.20 and p.21 / PDF p.27 and p.28', verification_note='VA-verified 2026-09-08 (§8.4.1 Mezcla, printed p.20-21 / PDF p.27-28) [VA] — the list runs across the printed page break, so it is quoted as three joined runs. CAVEAT: the page says the mixing system "puede estar compuesto por UNO O VARIOS de los siguientes sistemas", i.e. a multi-select; the field is a single-select enum (STAGED R-16)', verified_at=now() where id='2a2fc4fe-5947-48ff-a38f-58072ee6fca5' and verification_status not in ('verified_against_standard','corrected');

-- tank_sampling_device - §8.4.2 Equipo de muestreo, printed p.21 / PDF p.28
update public.fields set verification_status='verified_against_standard', verification_quote='El sistema de muestreo puede estar compuesto por los siguientes elementos principales - una tubería de muestreo equipada con una válvula, utilizada para recoger el líquido a cierta distancia de la pared interior del depósito. | Preferiblemente, se evitarán las posiciones extremas (superficie, borde y fondo del recipiente); - varios tubos de muestreo colocados a diferentes alturas. | - un muestreador lastrado, equipado con un sistema de apertura/cierre autosellante en su parte inferior (bola, válvula, etc.) para llenarlo hasta el nivel deseado; y - un by-pass o una derivación en una línea de recirculación asociada a un contenedor. — printed p.21 / PDF p.28', verification_note='VA-verified 2026-09-08 (§8.4.2 Equipo de muestreo, printed p.21 / PDF p.28) [VA] — the four enum values reproduce the four printed bullets. CAVEAT: the bullets are joined by "; y" (a conjunction), so the printed list describes components that may co-exist; the field is a single-select enum (STAGED R-16)', verified_at=now() where id='f9e9b821-4987-4549-8f5b-79573e40e992' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-08 "Homogenisierung, Konservierung, Transport & Lagerung" (7 rows) ----------

-- homogenization_done - §9.1 Homogeneización del volumen recogido, printed p.21-22 / PDF p.28-29
update public.fields set verification_status='verified_against_standard', verification_quote='Si el volumen de muestra requerido es tan grande que se necesitan varias extracciones y/o hay que llenar diferentes frascos con una misma muestra, deberá garantizarse la homogeneidad de la muestra. | Se recomienda llevar a cabo la etapa de homogeneización, utilizando un método validado. Se comprobará la eficacia del método de homogeneización (posición de la hélice, velocidad de agitación, duración de la homogeneización). — printed p.21 and p.22 / PDF p.28 and p.29', verification_note='VA-verified 2026-09-08 (§9.1 Homogeneización del volumen recogido, printed p.21-22 / PDF p.28-29) [VA] — the obligation is CONDITIONAL on multiple extractions / several bottles, and the validated-method sentence is "Se recomienda" (recommended). Block gate CR-025 quotes instead the un-hedged sentence "Este paso es esencial, incluso para las muestras con un bajo contenido de sólidos en suspensión." (printed p.22), which is the strongest anchor available', verified_at=now() where id='60fccd59-0e40-4660-a287-6953df6a3c05' and verification_status not in ('verified_against_standard','corrected');

-- homogenizer_type - §9.1, printed p.21-22 / PDF p.28-29
update public.fields set verification_status='verified_against_standard', verification_quote='Para volúmenes de muestra mayores (por ejemplo, > 5 l), los homogeneizadores con recipientes de muestra transportables y | con agitador magnético o mecánico deberían utilizarse. | Para volúmenes inferiores recogidos (≤5 l), puede aplicarse el método de laboratorio (por ejemplo, agitación manual, mezcla con varillas, etc.). — printed p.21 and p.22 / PDF p.28 and p.29', verification_note='VA-verified 2026-09-08 (§9.1, printed p.21-22 / PDF p.28-29) [VA] — the sentence runs across the printed page break and the extraction inserts a line break inside it, so it is quoted as three runs. Modality: "deberían utilizarse" (should) for the mechanical case, "puede aplicarse" (may) for the laboratory case - neither is a shall; no gate exists, which is proportionate', verified_at=now() where id='481e97d9-4e96-430c-8df0-2b960a1a88c8' and verification_status not in ('verified_against_standard','corrected');

-- collected_volume - §9.1, printed p.21-22 / PDF p.28-29
update public.fields set verification_status='verified_against_standard', verification_quote='Para volúmenes de muestra mayores (por ejemplo, > 5 l), los homogeneizadores con recipientes de muestra transportables y | Para volúmenes inferiores recogidos (≤5 l), puede aplicarse el método de laboratorio (por ejemplo, agitación manual, mezcla con varillas, etc.). — printed p.21 and p.22 / PDF p.28 and p.29', verification_note='VA-verified 2026-09-08 (§9.1, printed p.21-22 / PDF p.28-29) [VA] — the 5 l threshold is printed twice, as "> 5 l" (itself flagged "por ejemplo") and as "≤5 l"; unit l correct. NO gate ties collected_volume to homogenizer_type, so the printed threshold is not enforced (STAGED R-21)', verified_at=now() where id='efa7a4b6-4583-4d1e-bb5e-ff1b11e6b799' and verification_status not in ('verified_against_standard','corrected');

-- preservation_per_iso5667_3 - §9.3 Conservación y embalaje de las muestras, printed p.23 / PDF p.30
update public.fields set verification_status='verified_against_standard', verification_quote='El tipo de frascos de laboratorio utilizados para la recogida y el almacenamiento se indican en la norma ISO 5667-3 y deben definirse conjuntamente con el laboratorio. Pueden ser necesarios algunos tratamientos previos de la muestra, mediante acidificación, alcalinización (para el carbono radiactivo o los metales, por ejemplo), congelación o adición de agentes de etiquetado desde la recogida de la muestra. Consulte la norma ISO 5667-3. Para la conservación y la manipulación de las muestras destinadas al laboratorio, deben observarse las disposiciones establecidas por la norma ISO 5667-3. — printed p.23 / PDF p.30', verification_note='VA-verified 2026-09-08 (§9.3 Conservación y embalaje de las muestras, printed p.23 / PDF p.30) [VA] — "deben observarse" is shall-class. The substantive preservation requirements live in ISO 5667-3, which is not in the library, so anything numeric behind this attestation is NR', verified_at=now() where id='73908223-421b-4b62-b5db-b3b9b52df9b5' and verification_status not in ('verified_against_standard','corrected');

-- max_storage_time - §9.4.2 Tiempo, printed p.23 / PDF p.30
update public.fields set verification_status='verified_against_standard', verification_quote='El tiempo máximo de almacenamiento de las muestras entre el muestreo y el análisis deberá ajustarse a los requisitos definidos en las normas ISO 5667-3, ISO 5667-16 e ISO 19458. En caso contrario, deberá justificarse cualquier modificación de este período. En todos los casos, el tiempo máximo de almacenamiento de la muestra deberá acordarse entre el organismo de muestreo, el laboratorio y el cliente. — printed p.23 / PDF p.30', verification_note='VA-verified 2026-09-08 (§9.4.2 Tiempo, printed p.23 / PDF p.30) [VA] — this document prints NO holding-time number: the limit lives in ISO 5667-3 / -16 / ISO 19458 (NR). Block gate CR-028 is therefore a presence check ("max_storage_time IS NOT NULL"), which is the honest encoding here; the inconsistency is that the gate blocks on a field whose is_required is false (STAGED R-23)', verified_at=now() where id='9d9e752a-ec77-4918-947c-cbe59dce55af' and verification_status not in ('verified_against_standard','corrected');

-- transport_temperature - §9.4.3 Temperatura, printed p.23 / PDF p.30
update public.fields set verification_status='verified_against_standard', verification_quote='Para garantizar la integridad de la muestra entre el muestreo y la recepción en el laboratorio, las muestras deben almacenarse en un dispositivo de refrigeración capaz de mantener una temperatura de (5 ± 3) °C. | En el momento de la recepción en el laboratorio, las muestras deben almacenarse de acuerdo con las normas ISO 5667-3, ISO 5667-16 o ISO 19458. — printed p.23 / PDF p.30', verification_note='VA-verified 2026-09-08 (§9.4.3 Temperatura, printed p.23 / PDF p.30) [VA] — "(5 ± 3) °C" expands to 2 °C .. 8 °C, which is exactly what block gate CR-027 enforces, inclusive at both ends; unit C correct', verified_at=now() where id='cd7b0b80-6786-486c-b900-8b0e1879eca0' and verification_status not in ('verified_against_standard','corrected');

-- sample_traceability - §9.5.1 Muestras de rutina and §9.5.2 Muestras que pueden utilizarse con fines legales, printed p.24 / PDF p.31
update public.fields set verification_status='verified_against_standard', verification_quote='El operario de muestreo es responsable de la seguridad y la trazabilidad de las muestras, submuestras y documentos de registro de muestras a su cargo. | Si los contenedores se pierden, dañan o rompen durante el transporte, el operario de muestreo deberá registrarlo en el formulario de registro de muestras. Si interviene un mensajero, éste deberá hacer un registro similar mientras las muestras estén a su cargo. | Las normas que deben seguirse si las muestras van a utilizarse con fines legales pueden ser mucho más onerosas, dependiendo del sistema legal que opere en una jurisdicción concreta. — printed p.24 / PDF p.31', verification_note='VA-verified 2026-09-08 (§9.5.1 Muestras de rutina and §9.5.2 Muestras que pueden utilizarse con fines legales, printed p.24 / PDF p.31) [VA] — the anchor sentence of block gate CR-029 is a statement of RESPONSIBILITY, not a modal shall; the "deberá registrarlo" runs quoted as the second fragment are the shall-class parts of the same clause', verified_at=now() where id='52fa2438-8c33-48a0-aa52-8aa79b520fa3' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-09 "Qualitaetssicherung & Berichterstattung" (8 rows) ----------

-- written_contamination_instructions - §10.1 Evitar la contaminación, printed p.24 / PDF p.31
update public.fields set verification_status='verified_against_standard', verification_quote='Deben proporcionarse instrucciones específicas por escrito al personal encargado de la toma de muestras sobre los protocolos necesarios que deben seguirse para evitar la contaminación en el muestreo de aguas residuales. Se debería animar al personal de muestreo a documentar cualquier desviación de los riesgos previstos para facilitar la interpretación de los resultados. Es esencial evitar la contaminación durante el muestreo. — printed p.24 / PDF p.31', verification_note='VA-verified 2026-09-08 (§10.1 Evitar la contaminación, printed p.24 / PDF p.31) [VA] — "Deben proporcionarse" is shall-class; the documentation-of-deviations part is "Se debería animar" (should be encouraged), weaker than the field description implies. Block gate CR-030 sits on worksheet 08 while this field lives on worksheet 09 (mis-homed; STAGED R-5)', verified_at=now() where id='4d911460-b5b6-4a81-89bd-89a41973ce0e' and verification_status not in ('verified_against_standard','corrected');

-- gloves_used - §10.1, printed p.24 / PDF p.31
update public.fields set verification_status='verified_against_standard', verification_quote='El uso de guantes (por ejemplo, guantes de nitrilo sin polvo de un solo uso) para todas las operaciones (muestreo y acondicionamiento de la muestra) es necesario. Se recomienda encarecidamente que durante todas las operaciones de muestreo limitar los materiales intermedios. — printed p.24 / PDF p.31', verification_note='VA-verified 2026-09-08 (§10.1, printed p.24 / PDF p.31) [VA] — "es necesario" is shall-class for gloves in general, but the nitrile/powder-free/single-use specification is inside a "por ejemplo" parenthetical, which the field description states as if it were the requirement', verified_at=now() where id='3d206e2d-dfa4-4edd-8121-a373b1c52357' and verification_status not in ('verified_against_standard','corrected');

-- field_form_completed - §10.2 Identificación y registro de las muestras, printed p.25 / PDF p.32
update public.fields set verification_status='verified_against_standard', verification_quote='Toda la información debe ser reportada en el formulario de campo, especificando las condiciones ambientales, aspectos de la descarga, la presencia de cualquier contaminante, cualquier anomalía observada y las coordenadas precisas o la ubicación del punto o puntos de muestreo. | Los recipientes de las muestras deben estar identificados de forma clara e inequívoca para que los resultados analíticos posteriores puedan interpretarse correctamente. | No deben tomarse más muestras hasta que se hayan etiquetado todos los frascos de muestras. — printed p.25 / PDF p.32', verification_note='VA-verified 2026-09-08 (§10.2 Identificación y registro de las muestras, printed p.25 / PDF p.32) [VA] — "debe ser reportada" and "No deben tomarse más muestras hasta que se hayan etiquetado" are both shall-class, matching block gate CR-031. The referenced "Anexo D" (field-sheet example) is NOT PRESENT in the library copy (NR)', verified_at=now() where id='c56a3128-f4d1-4097-9031-94f56a566c06' and verification_status not in ('verified_against_standard','corrected');

-- sample_label_unique_code - §10.2, printed p.25 / PDF p.32
update public.fields set verification_status='verified_against_standard', verification_quote='Las muestras se identifican mediante una etiqueta preimpresa con los datos del lugar y un código único legible por máquina duplicado tanto en la etiqueta de la muestra como en el documento de registro de la muestra del laboratorio, así será necesario registrar menos detalles. — printed p.25 / PDF p.32', verification_note='VA-verified 2026-09-08 (§10.2, printed p.25 / PDF p.32) [VA] — the sentence is descriptive (present indicative, not a modal), which matches the field being is_required=false and carrying no gate', verified_at=now() where id='b525fc5b-512f-488f-9081-0b70fb426ed1' and verification_status not in ('verified_against_standard','corrected');

-- qa_qc_per_iso5667_14 - §10.3 Garantía y control de calidad, printed p.25 / PDF p.32
update public.fields set verification_status='verified_against_standard', verification_quote='Consulte la norma ISO 5667-14 para conocer todos los detalles de estas técnicas para su uso en el muestreo de aguas residuales. Todo el material que entre en contacto con la muestra debe someterse a medidas de control de calidad para garantizar que no haya contaminación y/o pérdida de analitos. | El equipo de muestreo debe ser revisado (Anexo H). En caso de incumplimiento, las desviaciones deben ser analizadas. Todos estos controles deben ser registrados. — printed p.25 / PDF p.32', verification_note='VA-verified 2026-09-08 (§10.3 Garantía y control de calidad, printed p.25 / PDF p.32) [VA] — "debe someterse" and "debe ser revisado" are shall-class, matching block gate CR-032. The referenced "Anexo H" (equipment checks) is NOT PRESENT in the library copy, so the check list this field attests to is NR', verified_at=now() where id='1f0d264f-cfc6-4960-89bc-d3a546d3daa0' and verification_status not in ('verified_against_standard','corrected');

-- report_items_recorded - §11.1 Informes analíticos, printed p.25 / PDF p.32
update public.fields set verification_status='verified_against_standard', verification_quote='Los detalles del informe de muestreo dependen de los objetivos del mismo. Deben anotarse todas las condiciones que puedan influir en los resultados analíticos. Las cuestiones que podrían considerarse para su inclusión son: — printed p.25 / PDF p.32', verification_note='VA-verified 2026-09-08 (§11.1 Informes analíticos, printed p.25 / PDF p.32) [VA] — "Deben anotarse todas las condiciones" is shall-class, matching block gate CR-033. CAVEAT: the ITEM LIST that follows (printed p.26) is explicitly optional - "Las cuestiones que PODRÍAN CONSIDERARSE para su inclusión son" - while the field description presents the twelve items as recorded requirements (STAGED R-24)', verified_at=now() where id='a0d90a5a-1ef8-4d27-961c-4e845b1cbb65' and verification_status not in ('verified_against_standard','corrected');

-- auto_sampler_traceability_recorded - §11.1, printed p.26 / PDF p.33
update public.fields set verification_status='verified_against_standard', verification_quote='En el caso de que se utilice un muestreador automático, también es necesario garantizar la trazabilidad de la siguiente información: -identificación del equipo utilizado -programación utilizada para el muestreo; -control paramétrico de las condiciones de uso (velocidad de aspiración, repetibilidad de los volúmenes tomados, etc.); -limpieza del material (sí o no) antes de su utilización; -diámetro del tubo de aspiración en mm; -longitud del tubo de aspiración en m; -velocidad de aspiración; -purga de las tuberías (sí o no) antes de su uso; -utilización de un colador (sí o no); -volumen total recogido; — printed p.26 / PDF p.33', verification_note='VA-verified 2026-09-08 (§11.1, printed p.26 / PDF p.33) [VA] — "es necesario garantizar la trazabilidad" is shall-class and, unlike the §11.1 report list above it, this list is NOT hedged; the ten encoded items match the printed items one for one, including the units mm and m', verified_at=now() where id='326368c4-f0c8-40d9-bc67-2e396c2a38d3' and verification_status not in ('verified_against_standard','corrected');

-- protocol_change_history - §11.2 Protocolos de muestreo, printed p.27 / PDF p.34
update public.fields set verification_status='verified_against_standard', verification_quote='Debe mantenerse un "historial" de los cambios en los protocolos y procedimientos de muestreo que permita a una persona que examine los datos la oportunidad de evaluar los impactos de los cambios de procedimiento, tanto en el campo como en el laboratorio, en la serie de observaciones recogidas. Los cambios en el laboratorio, como los límites de detección y la precisión, suelen registrarse, pero los cambios en los métodos de muestreo, los puntos de muestreo y el personal también deberían formar parte del registro. — printed p.27 / PDF p.34', verification_note='VA-verified 2026-09-08 (§11.2 Protocolos de muestreo, printed p.27 / PDF p.34) [VA] — "Debe mantenerse" is shall-class for the history itself; the extension to sampling methods/points/personnel is "deberían formar parte" (should). No gate reads this field', verified_at=now() where id='d548b33b-1cfa-4323-bbec-f98c475a2cbc' and verification_status not in ('verified_against_standard','corrected');

-- ---------- ws ISO-5667-10-10 "Sicherheitsvorkehrungen" (5 rows) ----------

-- risk_assessed_before_sampling - §12.1 Generalidades, printed p.27 / PDF p.34
update public.fields set verification_status='verified_against_standard', verification_quote='Los puntos tratados en esta sección no son exhaustivos, no pretenden cubrir todas las situaciones. La seguridad es responsabilidad de varias personas: el cliente, la agencia de muestreo y el subcontratista. | Las directrices de este documento no pueden sustituir a las normas y reglamentos locales y/o nacionales. El riesgo asociado al muestreo debe ser considerado antes de que se realice cualquier muestreo. — printed p.27 / PDF p.34', verification_note='VA-verified 2026-09-08 (§12.1 Generalidades, printed p.27 / PDF p.34) [VA] — "debe ser considerado antes de que se realice cualquier muestreo" is shall-class, matching block gate CR-034. That gate, however, sits on worksheet 09 while this field lives on worksheet 10 (mis-homed; STAGED R-5)', verified_at=now() where id='444bf768-4dde-4e4e-9d78-bef56f4a9a98' and verification_status not in ('verified_against_standard','corrected');

-- systematic_ppe_worn - §12.2 Seguridad del personal, printed p.27 / PDF p.34
update public.fields set verification_status='verified_against_standard', verification_quote='Los equipos de protección personal que deben utilizarse sistemáticamente para realizar todas las operaciones de muestreo son: zapatos y/o botas de seguridad, cascos, gafas, guantes desechables y guantes de manipulación, para protegerse de los riesgos de exposición a materiales tóxicos o patógenos (ingestión, inhalación, contacto con la piel). — printed p.27 / PDF p.34', verification_note='VA-verified 2026-09-08 (§12.2 Seguridad del personal, printed p.27 / PDF p.34) [VA] — "deben utilizarse sistemáticamente" is shall-class and the list is closed; block gate CR-035 is proportionate', verified_at=now() where id='3a813718-62e7-4bc2-86e4-8d1f7806e1e0' and verification_status not in ('verified_against_standard','corrected');

-- hazard_specific_ppe - §12.2, printed p.27 / PDF p.34
update public.fields set verification_status='verified_against_standard', verification_quote='Los equipos de protección individual que deben poseerse en función de los peligros que puedan encontrarse son: máscara de emergencia, máscara antigás, detector de gases (H2S, CO, O2, etc.), arnés de seguridad, trípode, parada de caída, dispositivo de alarma para el trabajador solitario, guantes resistentes a productos químicos (disolventes, hidrocarburos, etc.). — printed p.27 / PDF p.34', verification_note='VA-verified 2026-09-08 (§12.2, printed p.27 / PDF p.34) [VA] — hazard-dependent, so the field is correctly is_required=false; the encoded item list matches the printed one including the gases H2S, CO and O2', verified_at=now() where id='639eed53-b314-4788-b63e-e57becef3b1b' and verification_status not in ('verified_against_standard','corrected');

-- two_person_operation - §12.2, printed p.28 / PDF p.35
update public.fields set verification_status='verified_against_standard', verification_quote='En algunos casos en los que existen riesgos específicos, la operación de muestreo debe ser llevada a cabo por dos personas para garantizar la seguridad y dar la alerta si hay algún problema. Si no se cumplen las condiciones de acceso o seguridad del operario de muestreo, no se debe realizar el muestreo y se debe informar al cliente y al laboratorio de análisis. — printed p.28 / PDF p.35', verification_note='VA-verified 2026-09-08 (§12.2, printed p.28 / PDF p.35) [VA] — conditional shall ("En algunos casos en los que existen riesgos específicos"); the field is correctly is_required=false and carries no gate', verified_at=now() where id='9de75f8c-19cd-4e45-a412-768c349f7b6d' and verification_status not in ('verified_against_standard','corrected');

-- equipment_secured - §12.3 Seguridad de los equipos, printed p.28 / PDF p.35
update public.fields set verification_status='verified_against_standard', verification_quote='En el caso de los muestreadores automáticos o los equipos de muestreo instalados en el lugar, deben tomarse las precauciones adecuadas para no exponerlos a riesgos naturales, robos o vandalismo. Los equipos instalados in situ tampoco deben suponer un riesgo para el medio ambiente ni para el público. Las operaciones de muestreo en espacios confinados (cuenca, tubería, tanque, alcantarilla) y, en particular, en las redes de alcantarillado, requieren el cumplimiento de normas de seguridad específicas para el equipo. | El equipo de muestreo deberá cumplir el requisito pertinente para el uso de equipos en atmósferas potencialmente explosivas en el caso de que los equipos de muestreo se instalen en una atmósfera explosiva peligrosa o de la que se bombeen líquidos. — printed p.28 / PDF p.35', verification_note='VA-verified 2026-09-08 (§12.3 Seguridad de los equipos, printed p.28 / PDF p.35) [VA] — shall-class throughout, matching block gate CR-036. NOTE: §12.3 is printed on p.28 but is MISSING from the printed Contents, which stops at 12.2', verified_at=now() where id='db3f13d6-b575-4bf0-a0a0-ce2f6c9c4f8d' and verification_status not in ('verified_against_standard','corrected');

-- ============================ SECTION B - equations (3 rows) ============================

-- Formula (1) - §4.3.2, Fórmula (1), printed p.5 / PDF p.12
update public.equations set verification_status='verified_against_standard', verification_quote='si el período de muestreo abarca un año, los días de muestreo pueden determinarse mediante una fórmula. Un ejemplo es: | Fórmula (1) para un número de muestras (n), superior a unas 25 y de la Fórmula (2) para un número de muestras inferior a unas 25. | La fórmula (1) indica el número de días durante los cuales debe realizarse el muestreo. | Donde n Número de muestras; A Número aleatorio en un intervalo entre – 365/n y 0. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, Fórmula (1), printed p.5 / PDF p.12) [VA] — the formula BODY is one of the two passages destroyed in the text layer (144 of the 246 undecodable characters sit on this page), so it was READ FROM THE RENDERED PAGE IMAGE (PDF p.12 at 150 dpi). The page prints an explicit SERIES: "A + 365/n, A + 365x2/n, A + 365x3/n, ...., A + 365xn/n", which is the encoded sampling_day_k = A + 365*k/n. Nothing was quoted from the corrupt run. TWO discrepancies with the stored source_quote: it renders the bound as "± 365/n" where the page prints "– 365/n" (a minus), and it cites pág. 5 with no PDF page (STAGED R-13)', verified_at=now() where id='ba1bf923-06cc-46aa-aab2-40f0dfa7ae22' and verification_status <> 'verified_against_standard';

-- Formula (2) - §4.3.2, Fórmula (2), printed p.5 / PDF p.12
update public.equations set verification_status='verified_against_standard', verification_quote='Fórmula (1) para un número de muestras (n), superior a unas 25 y de la Fórmula (2) para un número de muestras inferior a unas 25. | La fórmula (2) indica el número de la semana durante la cual debe realizarse el muestreo. El día de cada semana debe determinarse de manera que las muestras se tomen todos los días de la semana. | Donde n Número de muestras; A Número aleatorio en un intervalo entre – 52/n y 0. — printed p.5 / PDF p.12', verification_note='VA-verified 2026-09-08 (§4.3.2, Fórmula (2), printed p.5 / PDF p.12) [VA] — READ FROM THE RENDERED PAGE IMAGE (PDF p.12 at 150 dpi) because the text layer of this page is destroyed. PRINTING DEFECT IN THE SOURCE: the page prints "B + 52/n, B + 52x2/n, A + 52x3/n, ...., A + 52xn/n" - the first two terms use B and the rest A, while the "Donde" legend defines only n and A and never defines B. The encoded sampling_week_k = A + 52*k/n follows the legend, which is the only reading the page supports (STAGED R-15). The stored source_quote again prints "± 52/n" where the page prints "– 52/n"', verified_at=now() where id='c7908fa3-c685-4d8d-a7cd-57e134794a85' and verification_status <> 'verified_against_standard';

-- Formula (3) - §7.2.2.3, Fórmula (3) and its legend, printed p.13-14 / PDF p.20-21
update public.equations set verification_status='verified_against_standard', verification_quote='Para las demás botellas individuales, toma el volumen (ml) que debe tomarse (Vn) en la botella. n es un porcentaje relativo al volumen total (Fórmula 3): | Vn: volumen de la muestra (ml) a tomar en la botella n | Vfinal: volumen total (ml) de las botellas del laboratorio | M3total: volumen total descargado (M3) | M3n: volumen descargado durante el muestreo de la botella n (M3) — printed p.13 and p.14 / PDF p.20 and p.21', verification_note='VA-verified 2026-09-08 (§7.2.2.3, Fórmula (3) and its legend, printed p.13-14 / PDF p.20-21) [VA] — the formula BODY is the second passage destroyed in the text layer (102 of the 246 undecodable characters sit on PDF p.21), so it was READ FROM THE RENDERED PAGE IMAGE (PDF p.21 at 150 dpi): "Vn = [Vfinal x (M3n / M3total)]", which is exactly the encoded V_n = V_final * (M3_n / M3_total). Nothing was quoted from the corrupt run', verified_at=now() where id='6a587ea8-30d9-4eb9-ad5a-b8d8fd60228d' and verification_status <> 'verified_against_standard';
